"""Hand-written parts of the AI guide: what each screen is for, the controls with their EXACT visible labels and stable ids,
and the click-by-click recipes. Everything that can be generated (tabs, presets, test kinds, routes, glossary) is generated elsewhere
(build.py) and cross-checked against this file by tests/test_aiguide.py and scripts/e2e_aiguide.py, so this cannot silently go stale.

Control ids follow one rule (static/aiguide.js): data-testid = <screen>-<slug of the visible label>; every id below is verified against
the real page by the Playwright sweep (scripts/e2e_aiguide.py). Select it with the CSS selector [data-testid="..."]."""
from __future__ import annotations

from typing import Dict, List, Optional, Tuple

# ---------------------------------------------------------------------------------------------- controls
# (testid, exact visible label or aria-label, what it does)
C = lambda tid, label, what: (tid, label, what)

