            C("refresh-chip", "Live", "Small status at the top of Run and Results: '● Live' (updates arrive by themselves), '↻ Updating every 2 s' (the live connection is down, so the screen asks the Pi for news by itself: every 2 s while a test runs, every 10 s otherwise) or 'Paused' (auto-refresh is off)."),
            C("refresh-now", "↻ Refresh", "Updates this screen right now."),
            C("refresh-auto", "Auto-refresh", "Checkbox: turns the automatic updating on or off (remembered in this browser)."),
            C("results-session", "Session", "Dropdown to choose which session to look at."),
            C("results-new-session", "＋ New session", "Starts a new session (asks for a name in a dialog)."),
            C("results-more-session-actions", "More ▾", "Opens a small menu with the rarely used session tools: Rename session, Clear tests (and the greyed-out USB button when no drive is plugged in)."),
            C("results-rename-session", "Rename session", "In the More menu: renames the session."),
            C("results-clear-tests", "Clear tests", "In the More menu: deletes every test in the session (asks to confirm; export first)."),
            C("repeat-pdf", "📄 PDF with combined summary", "Scheduled repeats (Results, card 'Scheduled repeats' > Combined summary): a PDF with the combined summary page and every run of the schedule."),
            C("results-export-zip", "⤓ Export ZIP", "Downloads the whole session (CSV + JSON of every test) as a .zip. Hidden while the session has no tests."),
