            C("results-save-to-usb-drive", "💾 Save to USB drive", "Copies the session export to a plugged-in USB drive. Next to the exports when a drive is plugged in; otherwise greyed out inside the More menu."),
            C("results-row-<n>", "Open test: <name> · <when> (<PASS|FAIL>)", "A row of the list of tests (keyboard-focusable; n = the test's number): opens that test below the list."),
            C("results-group-<n>", "Open test: <name><pi ⇄ pi> · Both ways at once · <when> (<PASS|FAIL>)", "A test with several links (Both ways, or one Pi to several Pis) as ONE row (n = the group number): click it to open the first link and to fold the per-link lines in or out."),
            C("result-ends", "", "Small text under the name of a row: who sent to whom, for example 'pi1 → pi2 · Round trip', 'pi1 ⇄ pi2 · Both ways at once' or 'pi1 → pi2, pi3 · 2 links'."),
            C("results-row-direction-<n>", "Open test: ↳ <from → to> · Round trip · <when> (<PASS|FAIL>)", "One link of a multi-link test (indented line under the group row; n = that link's test number): opens that link."),
            C("result-header", "", "Card above the verdict of the opened test: who sent, who received, how it was judged, and the marks."),
            C("result-links", "", "Multi-link tests only: the links table at the top of the result (all links of the test)."),
            C("result-links-banner", "", "Heading of the links table: 'All 2 links within the limit' or '1 of 2 links over the limit'."),
            C("result-link-<id>", "", "One row of the links table (id = that link's test number): the link's name, p99, Lost and verdict; the open link is highlighted; click another row to open that link."),
            C("result-tester", "", "The tester line under the verdict banner: the tester lamp of the whole run (green line 'Pi OK', amber 'Check the Pi' or red 'The Pi is the limit' with the Pi's name and the reason). Shown on stored results of tests run with a version that has the lamp."),
