# ---------------------------------------------------------------------------------------------- recipes
def click(tid, label, note=""): return dict(do="click", tid=tid, label=label, note=note)
def typ(tid, label, value, note=""): return dict(do="type", tid=tid, label=label, value=value, note=note)
def choose(tid, label, option, note=""): return dict(do="choose", tid=tid, label=label, option=option, note=note)
def goto(tab, note=""): return dict(do="goto", tid=f"tab-{tab}", tab=tab, note=note)
def see(text, expect=None): return dict(do="see", text=text, expect=expect)


TRIP_COMMON_END = [
    see("Look at the Start bar at the bottom of the page: the check runs by itself (and again after every change). Green chips such as '✓ <name> answered' are fine. A red or amber row above the bar explains what to fix (see 'Why did it fail' in section 6) and ▶ Start stays greyed out while a row is red. The sentence in row 3 (and in the bar) says exactly what will run. To change limits first, open row 4 (recipe 'Change the limits')."),
    click("nt-start", "▶ Start", "The Start test button. Enabled once the check has finished with no red row. (Optional before it: the 'Job' line, selector [data-testid=\"job-line\"], to note site / link / who; and '💾 Save', selector [data-testid=\"nt-save\"], to keep the test in your list.)"),
    see("The Run screen opens with the banner '● RUNNING'. It finishes by itself; the banner then shows ✓ PASS or ✕ FAIL.", "RUNNING"),
]
NEW_TEST = click("setup-create-custom-test", "＋ New test", "Opens the New test page with four rows (Port, Protocol, From → To, Traffic); rows 1 to 3 are open. Or click ▶ Run on a test card: the same page, already filled in with that test (its rows start closed: tap a row's header to open it).")
