# which recipe runs which kind of test (build.py fails loudly for a preset whose transport/kind has no entry => the guide cannot go stale)
RECIPE_FOR_TRANSPORT = {
    "serial": "run-trip-serial", "udp": "run-trip-ethernet", "tcp": "run-trip-ethernet",
    "goose_l2": "run-goose", "goose_l3": "run-goose", "generator": "run-generator", "sniffer": "run-sniffer",
}
RECIPE_FOR_PRESET = {
    "DER trip \u2014 Mirrored Bits mode": "run-mirrored-bits","Back-to-back baseline": "run-baseline", "Overnight soak": "run-soak"}   # exceptions to the transport rule

KIND_ABOUT = {
    "trip": "Trip test (Setup screen: ＋ New test, or ▶ Run on a test card): one Pi sends a small message at a steady interval, the Pi at the far end (or several far Pis, one link each) answers it (round trip), and the sending Pi measures the delay of every message. Or it times one direction only (one way), or each link runs both ways at the same time. Used for protection / Mirrored-Bits-style signals. Verdict = PASS when the chosen percentile of messages is within the delay limit and loss is within the allowed percentage.",
    "generator": "Traffic generator (Generator screen): sends one or more streams of UDP / TCP / raw IP / raw Ethernet traffic at a set rate and size, each from one Pi to another (several Pis to several Pis is possible), and measures throughput, loss, delay, jitter against your pass limits, in total and per pair of Pis.",
    "sniffer": "Sniffer (Sniffer screen): passively captures Ethernet, serial or Wi-Fi traffic on this Pi into .pcapng files and summarises protocols and errors. No pass/fail on delay: the result is SAVED (or STOPPED if storage ran out).",
}
