# ---------------------------------------------------------------------------------------------- how to read results
READING = [
    ("Verdict banner", "✓ PASS = every requirement was met. ✕ FAIL lists the reasons in words (for example 'p99 74 ms is over the 60 ms limit' or 'loss 0.4 % is over 0 %'). ✕ NO RESULT / COULD NOT RUN = the test never ran; the text says why (the other Pi did not answer, no serial port, a port is busy, no permission). A test with several links (several far Pis, or Both ways) has one banner ('All 2 links meet the requirement.' or '1 of 2 links do not meet the requirement.') with a line per link, and Results starts with a links table."),
    ("Who sent to whom", "The header above the verdict names the Pi that sent and the Pi that received (by their names) and whether the verdict is judged on the round trip or on the one-way delay. A both-ways test is one entry with two arrows; open either direction."),
    ("Typical (p50)", "Half of the messages were faster than this, half slower: the normal delay."),
    ("p95 / p99", "95 % / 99 % of messages were at least this fast. p99 is what the default pass rule uses: the slowest 1 in 100 are ignored."),
    ("Slowest", "The single slowest message. If only this is over the limit but p99 is fine, one rare spike happened."),
    ("Lost", "Messages with no reply within 'Give up after (ms)'. Loss is the main reason for a FAIL on cellular links."),
    ("Over the limit", "Messages that arrived, but later than the delay limit (they count as late, not lost)."),
    ("Jitter", "How much the delay changes from one message to the next. High jitter with fine p50 points to a congested or handing-over link."),
    ("Duplicates / out of order / corrupted", "Messages received twice, in the wrong order, or damaged. Anything above zero is worth investigating (a bad cable, a misconfigured radio, or two Pis answering the same port)."),
    ("First message after a quiet period", "Table of the 'quiet gap' checks: after the link idled for N seconds, how long the next message took. Cellular radios sleep when idle, so this is often the worst case and the reason a trip would be late."),
    ("Each direction", "Separate delay for each direction (from → to and to → from). Only shown when both clocks are synced (offsets are printed); otherwise only round trip is shown."),
    ("TCP session", "Connect time, reconnects (with outage length) and stalls (silent drops): how fast TCP recovers after a dropped session."),
    ("GOOSE details", "Events sent / seen, retransmissions, sqNum gaps (lost repeat frames), TAL expiries (the receiver would have declared the sender dead), frame size, whether the VLAN tag survived."),
    ("Generator result", "Sent / Received Mb/s, Lost, Delay p99, a Streams table with per-stream loss, delay (typical / p99 / slowest), jitter, round trip, duplicates and reordering, and 'Per pair of Pis' with one row per sender → receiver pair. One-way delay needs synced clocks."),
    ("Sniffer result", "Packets, data, Errors / CRC failures (a failed CRC means a corrupted serial or Ethernet frame), longest quiet gap, protocol shares, top talkers, DNP3 / Modbus function counts, Wi-Fi networks heard, and the capture files to download."),
]

FAILURES = [
    ("Could not run: '<name> did not answer'", "The other Pi's app is not running, the address or port is wrong, a firewall blocks it, or this Pi cannot reach it. Check the Pi's row in Settings → Pis on this network (✓ reachable?), the address and the port (default 20500), the cables, then change anything or press '↻ Look again' in row 3 (the check runs again by itself). 'A password is needed': save that Pi's password in Settings → Pis on this network → 'Set password'."),
    ("'Choose where to send' / 'Address needed'", "No far Pi is chosen in row 3 of the New test page, or '＋ Type an IP address' has no address. Tick a Pi under 'To' (or 'From' after Swap) or type its address."),
    ("'No other Pi found yet'", "No other Pi is on this network, or the network blocks the way Pis find each other. Add it by its IP address with '＋ Add a Pi by IP' (recipe 'Add another Pi to the list')."),
    ("A direction is greyed out / 'is not possible here'", "'→ One way' needs both Pis' clocks synced (Settings → Time source); '⇆ Both ways' needs UDP or TCP (not serial, GOOSE or Mirrored Bits) and a Pi of the list (not a typed address). Tap the greyed choice: the reason appears."),
    ("The lamp under the banner is amber or red ('Check the Pi' / 'The Pi is the limit')", "The Pi that measures, not the link, may be the problem: it sent late, its processor was busy, it dropped received messages, Wi-Fi power saving was on or a USB-serial adapter adds delay. Fix what the line says and run again (recipe 'Read the tester lamp')."),
    ("'That port is busy'", "A serial port or Ethernet port is being used by another test on that Pi (a port cannot send and answer at once). Wait for it to finish or pick another port."),
    ("Could not run: no serial port", "The USB-serial adapter is not plugged in or has no permission. Plug it in, press '↻ Look again' in row 1 and pick it there as a chip (for the far Pi: 'Port on <name>' under row 3)."),
    ("Serial test shows 'USB adapter adds delay'", "FTDI adapters hold data up to 16 ms by default. Press 'Fix now (set to 1 ms)' in the amber check row above the Start bar of the New test page."),
    ("FAIL: p99 over the limit, nothing lost", "The link is too slow for the requirement. Compare with a 'Back-to-back baseline' to rule out the Pis; look at 'First message after a quiet period' (idle wake-up) and at Jitter; check radio signal and carrier priority (DSCP 46)."),
    ("FAIL: messages lost", "Radio signal, congestion or a bad cable. Re-run with 'Message every (ms)' unchanged and compare; try 'Simulate a bad link' only to rehearse, never to diagnose."),
    ("Only the quiet-period rows are slow", "The radio sleeps when idle. This is a link property, not a Pi problem."),
    ("'Each direction' missing", "The Pis' clocks are not synced (Settings → Time source: one Pi serves the time and the others follow it). Round trip is still valid."),
    ("GOOSE: 'Missing permission for GOOSE'", "This copy of the app was started without raw-socket permission (rootless install). A full install with sudo gives it."),
    ("'Bad-link simulation not allowed'", "The app lacks the netem permission (full install needed)."),
    ("Sniffer: 'No capture tool'", "tshark / dumpcap is not installed (full install installs it)."),
    ("A test says 'already running'", "Only one test runs at a time on a Pi. Press '■ Stop test' on the Run screen first."),
    ("Lost the page after a network change", "The Pi reverts the change by itself after 90 s unless you press 'Keep'. Reconnect (the page of the new address, or the Pi's Wi-Fi) and press 'Keep' in the bar at the top, or wait for it to revert."),
]

# extra glossary terms (the app's own tooltips are added automatically from static/ui.js)
GLOSSARY_EXTRA = {
    "Pi name": "The friendly name of a Pi (default: its host name, e.g. pi1). Shown top right, in every Pi list and on results; set in Settings → This Pi. It is also the Wi-Fi name when the Pi is an access point.",
    "This Pi / controller": "The Pi whose web page you are on. It starts tests (on itself or on other Pis), collects the numbers and stores the results. Every Pi is the same app; there are no fixed roles.",
    "Pis on this network": "The other Pis this Pi knows: found by themselves (mDNS) or added by IP address. Listed in Settings and as the tick list under 'To' in row 3 of the New test page (and in the Generator's From / To lists).",
    "From / To": "Row 3 of the New test page: 'From' is this Pi (the Pi whose page you are on) and 'To' is a tick list of the Pis at the far end. Tick one Pi or several (one link each). '⇅ Swap' makes the far Pis the senders. 'To' can also be a typed IP address (UDP / TCP).",
    "Link": "One sender → receiver pair of a test. A test between two Pis has one link (two with '⇆ Both ways'); a test with three Pis ticked has three links. Run and Results show several links in ONE table, one row per link.",
    "Mark (⚑)": "A flag you drop on a running test with '⚑ Mark' (optional name, for example 'antenna moved'). It shows on the charts, in the result, the PDF and the CSV column 'mark'; the numbers 'Since ⚑N' show next to 'Whole test'. The verdict is always the whole test.",
    "tester lamp": "One line on Run (and in the result as the tester line) that says whether the Pi itself keeps up: a green line 'Pi OK', amber 'Check the Pi', or red 'The Pi is the limit', with the Pi's name and the reason (sending ran late, processor busy, receive drops, clocks, Wi-Fi power saving, slow USB adapter). Amber or red: a bad number may be the Pi, not the link.",
    "Port (row 1)": "The port of THIS Pi the test uses: 'Automatic' (the port that reaches the far Pi) or a named Ethernet, Wi-Fi or serial port (eth0, wlan0, ttyUSB0). The Protocol in row 2 offers only what that port can carry.",
    "Direction": "'⇄ Round trip' (the far end sends each message straight back; the classic test, default), '→ One way' (needs synced clocks; '⇅ Swap' for the other way) or '⇆ Both ways' (each link in both directions at the same time, UDP and TCP).",
    "Reflector": "What every Pi always runs: it answers UDP and TCP test messages on port 20500 (and claims a serial or Ethernet port only while a test uses it), so any Pi can send to any other without anything being started.",
    "Time source": "The Pi whose clock the others follow (Settings → Time source). One-way delay needs both Pis on the same clock; the default is automatic: the Pi that was set up first serves the time.",
    "Access point (AP)": "The Pi makes its own Wi-Fi (name = the Pi's name) that phones and laptops join, then open the Pi's web page. New installs start like this, with Ethernet for the internet and for testing. Set in Settings → Network.",
    "Trip signal / Mirrored Bits": "A small protection message sent repeatedly between relays (here emulated as a short message every 10 ms). A late or lost message can delay a breaker trip.",
    "DER": "Distributed energy resource (solar, storage) connected to the grid; the link between it and the utility must meet a delay limit (here 60 ms).",
    "Percentile (p50, p95, p99)": "p99 = the delay that 99 out of 100 messages beat.",
    "Round trip (RTT)": "Time from the sending Pi sending a message to its echo coming back from the other Pi.",
    "Quiet-period check": "Stay silent for N seconds, then time the next message: shows how long an idle radio takes to wake up.",
    "Netem / bad-link simulation": "Linux traffic control that adds artificial delay, jitter and loss on the sending Pi's network port.",
    "Pre-flight check": "Automatic health check before a test (the check in the Start bar of the New test page, which runs by itself whenever something changes) or before a capture (Sniffer: '✓ Run pre-flight check').",
    "Safety net (keep or revert)": "A network change that could cut your connection is undone by the Pi after 90 seconds unless you reconnect and press 'Keep'.",
    "Custom test": "A test you build yourself in Setup with '＋ New test' (port, protocol, far Pis, rate, length, pass limits) and keep with '💾 Save'. It is saved like a profile in the Setup list; Edit changes it.",
    "Session": "A named folder of related tests, e.g. one site visit.",
    "Preset / profile": "A preset is a built-in read-only test; a profile (saved test) is your editable copy. Both are 'tests' on the cards.",
    "pcapng": "Capture file format that Wireshark opens.",
    "SPAN / mirror port": "A switch port that receives a copy of other ports' traffic.",
    "BPF filter": "tcpdump-style capture filter, e.g. tcp port 502.",
    "CRC": "Check value at the end of a serial frame (DNP3, Modbus RTU); a failure means the frame was corrupted.",
    "Modbus RTU / DNP3": "Serial SCADA protocols; the sniffer decodes both and checks CRCs.",
    "VLAN / priority (802.1Q)": "A tag on Ethernet frames carrying a priority 0-7; GOOSE normally uses priority 4.",
    "sqNum / stNum": "GOOSE counters: stNum changes with each new event, sqNum counts repeats; a gap in sqNum means repeat frames were lost.",
    "Chrony / clock sync": "Time service that keeps the Pis' clocks together (needed for one-way delay).",
    "Rootless install": "An install without sudo: UDP, TCP and serial tests and the UI work; GOOSE raw sockets, bad-link simulation and the sniffer need the full install.",
}

